async function probeLink(x){if(x.youtube_id){let r=await fetch('https://www.youtube.com/oembed?url='+encodeURIComponent('https://www.youtube.com/watch?v='+x.youtube_id)+'&format=json',{signal:AbortSignal.timeout(8000)});return{ok:r.ok,status:r.status}}let raw=String(x.video_url||x.video_id||''),u;try{u=new URL(raw)}catch{return{ok:false,status:'bad-url'}}if(!/^https?:$/.test(u.protocol))return{ok:false,status:'bad-url'};try{let r=await fetch(u,{method:'HEAD',redirect:'follow',signal:AbortSignal.timeout(8000),headers:{'user-agent':'Mozilla/5.0 ArielMoviesLinkCheck/1.0'}});if([401,403,405,501].includes(r.status))return{ok:true,status:r.status};return{ok:r.status<400,status:r.status}}catch(e){try{let r=await fetch(u,{method:'GET',redirect:'follow',signal:AbortSignal.timeout(8000),headers:{'user-agent':'Mozilla/5.0 ArielMoviesLinkCheck/1.0',range:'bytes=0-0'}});if([401,403].includes(r.status))return{ok:true,status:r.status};return{ok:r.status<400,status:r.status}}catch(e2){return{ok:false,status:'error'}}}}
async function runLinkScan(batchSize){let items=scanTargets();overrides.linkScan=overrides.linkScan||{offset:0,broken:{},checked:0};let ls=overrides.linkScan;ls.broken=ls.broken||{};if(ls.offset>=items.length)ls.offset=0;let slice=items.slice(ls.offset,ls.offset+batchSize);linkScanState.batchTotal=slice.length;linkScanState.batchDone=0;for(let n=0;n<slice.length&&!linkScanState.stop;n+=6){await Promise.all(slice.slice(n,n+6).map(async x=>{let id=String(x.id||x.custom_slug);try{let r=await probeLink(x);if(r.ok)delete ls.broken[id];else ls.broken[id]={title:String(x.series_name||x.title||'').slice(0,120),status:String(r.status),at:new Date().toISOString()}}catch(e){}linkScanState.batchDone++}));if(n%120===0&&n>0)await saveOverrides().catch(e=>console.error('linkscan save',e.message))}ls.offset+=slice.length;ls.checked=(ls.checked||0)+slice.length;ls.lastRun=new Date().toISOString();if(ls.offset>=items.length){ls.completedCycle=ls.lastRun;ls.offset=0}let bk=Object.keys(ls.broken);if(bk.length>2000)ls.broken=Object.fromEntries(bk.slice(-2000).map(k=>[k,ls.broken[k]]));await saveOverrides()}
setInterval(()=>{if(analyticsDirty>0){analyticsDirty=0;saveOverrides().catch(e=>console.error('analytics flush',e.message))}},10*60000).unref();
